/* === GLOBAL BASE CSS === */
@import "https://at.alicdn.com/t/c/font_4441878_79ndpblv9x9.css";
@import "https://at.alicdn.com/t/c/font_4389188_4gtbloa6zjm.css";
html {
    color: #666;
    font-size: 12px;
    font-family: Arial, Helvetica, sans-serif;
    text-align: left;
    word-break: break-all;
    -webkit-font-smoothing: antialiased;
}
body,
div,
dl,
dt,
dd,
ul,
ol,
li,
h1,
h2,
h3,
h4,
h5,
h6,
pre,
code,
form,
fieldset,
legend,
input,
textarea,
p,
blockquote,
th,
td,
hr,
button,
article,
aside,
details,
figcaption,
figure,
footer,
header,
hgroup,
menu,
nav,
section {
    margin: 0;
    padding: 0;
    border: 0;
}
body {
    cursor: inherit;
    background-color: #f2f3f5;
    overflow-y: scroll;
}
blockquote,
q {
    quotes: none;
}
blockquote:before,
blockquote:after,
q:before,
q:after {
    content: "";
    content: none;
}
:focus {
    outline: 0;
}
ins {
    text-decoration: none;
}
del {
    text-decoration: line-through;
}
li {
    list-style: none;
}
table {
    width: 100%;
    border-collapse: collapse;
    border-spacing: 0;
}
address,
caption,
cite,
code,
dfn,
em,
th,
var,
i,
b {
    font-style: normal;
    font-weight: normal;
}
code,
kbd,
samp,
pre,
tt,
var,
button,
input,
select,
textarea {
    font-family: Helvetica, Arial, sans-serif;
    font-size: 100%;
}
hr {
    background: #ddd;
    color: #ddd;
    clear: both;
    float: none;
    width: 100%;
    height: 0.1em;
    margin: 0.5em 0;
    border: none;
}
hr.space {
    background: #fff;
    color: #fff;
}
/********************文本格式************************/
h1,
h2,
h3,
h4,
h5,
h6,
b {
    font-size: 100%;
    font-weight: normal;
}
cite,
em,
dfn {
    font-style: normal;
}
.fs14 {
    font-size: 14px;
}
.blue,
.blue a,
a.blue:link,
a.blue:visited {
    color: var(--general);
    cursor: pointer;
}
a {
    color: #333333;
    text-decoration: none;
    outline: none;
    transition: color 0.2s ease 0s;
}
a:hover {
    color: var(--general) !important;
    background: var(--main-btn-hover-bg);
    text-decoration: none;
}
::selection {
    background: var(--main-bg);
    color: var(--main-text);
    /* Safari */
}
::-moz-selection {
    background: var(--main-bg);
    color: var(--main-text);
    /* Firefox */
}
.price {
    font-size: 12px;
    font-weight: normal;
}
.price .util {
    font-size: 12px;
}
.mr10 {
    margin-right: 10px;
}
.ml10 {
    margin-left: 10px;
}
.mt10 {
    margin-top: 10px;
}
.mb10 {
    margin-bottom: 10px;
}
.gif-loading {
    background: url("/assets/images/common/loading.gif") no-repeat;
    background-size: 100% 100%;
    width: 20px;
    height: 20px;
}
.container {
    width: 1190px;
    margin: 0px auto;
    padding: 0;
    clear: both;
}
.red {
    color: #ff4040;
}
.btn-css3 {
    background: #ff6c6c;
    border: 1px solid #ff5e5e;
    color: #fff;
    cursor: pointer;
    border-radius: 2px;
    display: inline-block;
    height: 16px;
    line-height: 16px;
    padding: 5px 12px;
    text-align: center;
    text-decoration: none;
}
.btn-css3:hover {
    text-decoration: none;
    box-shadow: 0 1px 1px rgba(0, 1, 1, 0.08);
    cursor: pointer;
    color: #fff;
}
.flex {
    display: flex;
}
.flex-column {
    flex-direction: column;
}
.justify-start {
    justify-content: flex-start;
}
.justify-end {
    justify-content: flex-end;
}
.justify-center {
    justify-content: center;
}
.justify-between {
    justify-content: space-between;
}
.justify-around {
    justify-content: space-around;
}
.align-start {
    align-items: flex-start !important;
}
.align-end {
    align-items: flex-end;
}
.align-center {
    align-items: center;
}
.align-baseline {
    align-items: baseline;
}
.flex-wrap {
    display: flex;
    flex-wrap: wrap;
}
.hand-pointer,
a {
    cursor: pointer;
}
.ellipsis {
    white-space: nowrap;
    /* 防止文本换行 */
    overflow: hidden;
    /* 隐藏超出容器的部�?*/
    text-overflow: ellipsis;
    /* 当文本溢出时显示省略�?*/
}
.ellipsis2 {
    white-space: normal;
    overflow: hidden;
    text-overflow: ellipsis;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
}
.sticky-element {
    position: sticky;
    top: -0.5px;
    z-index: 1;
}
.icon-star {
    background-image: url("/assets/images/common/icon-star.png");
    background-repeat: no-repeat;
    display: inline-block;
    height: 14px;
    overflow: hidden;
    width: 65px;
}
.icon-star-5 {
    background-position: 0 1px;
}
.icon-star-4half {
    background-position: 0 -15px;
}
.icon-star-4 {
    background-position: 0 -32px;
}
.icon-star-3half {
    background-position: 0 -45px;
}
.icon-star-3 {
    background-position: 0 -67px;
}
.icon-star-2half {
    background-position: 0 -74px;
}
.icon-star-2 {
    background-position: 0 -100px;
}
.icon-star-1half {
    background-position: 0 -104px;
}
.icon-star-1 {
    background-position: 0 -132px;
}
.icon-star-half {
    background-position: 0 -133px;
}
.icon-star-0 {
    background-position: 0 -149px;
}
.icon-gou {
    display: none;
    /* 三角�?*/
    /* 三角形勾 */
}
.icon-gou::after {
    content: "";
    position: absolute;
    bottom: 0px;
    right: 0px;
    color: var(--main-text);
    border-bottom: 15px solid var(--general);
    border-left: 15px solid transparent;
}
.icon-gou::before {
    content: "";
    position: absolute;
    width: 3px;
    height: 5px;
    background: transparent;
    bottom: 2px;
    right: 2px;
    border: 2px solid white;
    border-top: none;
    border-right: none;
    transform: rotate(332deg);
    z-index: 1;
    transform: rotateY(180deg) rotate(329deg);
}
